package com.shopsphere.config; import org.springframework.cache.annotation.EnableCaching; import org.springframework.context.annotation.*; import org.springframework.data.redis.cache.*; import org.springframework.data.redis.connection.RedisConnectionFactory; import java.time.Duration; @Configuration public class CacheConfig { @Bean RedisCacheConfiguration redisCacheConfiguration(){return RedisCacheConfiguration.defaultCacheConfig().entryTtl(Duration.ofMinutes(10)).disableCachingNullValues();} }